import React, { useState } from 'react';
import { View, TouchableOpacity, Text } from 'react-native';

export default function EquipmentFilter() {
  const equipmentNameList = ["Dumbbell", "Barbell", "Bodyweight", "Machine", "Other"];

  const [equipSelect, setSelect] = useState<{ [eid: string]: boolean }>({});

  const selectToggle = (eid: string) => {
    setSelect(prevState => ({
      ...prevState,
      [eid]: !prevState[eid],
    }));
  };

  const selectedEquipment = equipmentNameList.filter(equipment => equipSelect[equipment]);

  const filteredList = selectedEquipment.length ? selectedEquipment : equipmentNameList;

  return (
    <View>
      {filteredList.map((equipment, index) => (
        <TouchableOpacity
          key={index}
          className=''
          style={{ backgroundColor: equipSelect[equipment] ? '#303030' : '#1E1E1E' }}
          onPress={() => selectToggle(equipment)}
        >
          <Text className='my-[12px] text-[20px] text-slate-200'>
            {equipment}
          </Text>
        </TouchableOpacity>
      ))}
    </View>
  );
}

